(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sm"] = {"ui":{"skip":"Alu i le anotusi","back":"← Toe foʻi i AI-gile","lang.button":"Gagana: {name}","lang.dialog":"Filifili se gagana","lang.search":"Suʻe gagana","lang.none":"E leai se gagana e tutusa","lang.notYet":"E leʻi faaliliuina le {name}","theme.aria":"Sui mai le autu malamalama i le pogisa","theme.toLight":"Sui i le autu malamalama","theme.toDark":"Sui i le autu pogisa","words.underline":"Tusi se laina i lalo o nei upu i le itulau","words.underlineHelp":"Tuu le kesa i luga pe tago i se upu e iai togi e vaai ai i lona uiga.","index.title":"AI-gile: lau ʻau AI faatupu polokalama, i le tasi laupapa","index.description":"O le AI-gile o se laupapa kanban mo ʻau tusi polokalama AI. E latou galulue a e moe oe; e te maua se faaputuga puupuu o mea e te filifili ai, suʻesuʻe ma talia.","hero.logoAlt":"Ata o le laupapa AI-gile","hero.h1.html":"Lau ʻau AI faatupu polokalama, i le tasi&nbsp;laupapa.","hero.alpha":"🐣 Pre-alpha tapunia","hero.alphaTitle":"Muamua ma le i uma: faafetai i lou taumafai!","hero.lede":"E latou fausia a e moe oe. E te ala mai i se faaputuga puupuu: ni nai fesili, ni nai mea e suʻe, ma le tasi pe lua taimane viole. Kiliki, talia, ma toe foʻi i lau kofe.","dl.windows":"Polokalama Windows","dl.browser":"Tatala i lau browser","dl.soon":"E le o toe umi","dl.notify":"🔔 Logo mai ina ua tatala","dl.notifySmall":"Alpha poʻo le beta","hero.secondary":"Agile, ae e le manaʻomia lava e le ʻau le kofe o le fono puupuu. (Ae latou te faia pea fono puupuu.)","pitch.h2":"AI-gile i le tele o upu e te manaʻo ai","pitch.lede":"Filifili se umi, mai le upu e tasi i le 144. O umi taʻitasi o se faamatalaga tuʻufaatasi, na tusia mo lena lapopoa. Toso le faʻasolo pe faaaoga ki aū o le keyboard.","pitch.rangeLabel":"Umi i upu","pitch.dice":"🎲 isi lomiga","pitch.words.one":"{n} upu","pitch.words.other":"{n} upu","pitch.letters.one":"{n} mataitusi","pitch.letters.other":"{n} mataitusi","pitch.chars.one":"{n} mataitusi","pitch.chars.other":"{n} mataitusi","count.line.html.one":"{n} kāte i luga o le laupapa nei","count.line.html.other":"{n} kāte i luga o le laupapa nei","features.aria":"O le a le mea e faia","f.pile.h":"Le tasi faaputuga mo oe","f.pile.html":"O <b>Mo oe</b> e tuufaatasia mea uma o loo faatali ia te oe, i poloketi uma: fesili, mea e suʻesuʻe, galuega e na o le tagata e mafai ona faia. O lau laina e taʻu atu le mea o le a sosoo ai ma le umi.","f.sleep.h":"ʻAu e galulue a e moe oe","f.sleep.p":"O poloketi taʻitasi e iai se taʻitaʻi ma se ʻau o sooupu AI. Tusi se faamatalaga i luga o se kāte ona ala lea o le ʻau, faia le galuega, ma toe tuuina atu ma laasaga e mafai e se tagata vaivai ona mulimuli ai.","f.tester.h":"E muamua siaki e se AI suʻesuʻe","f.tester.p":"Aʻo leʻi oo atu se mea ia te oe, e mulimuli le suʻesuʻe i laasaga i se kopi o le polokalama ma faaali le mea na ia vaai i ai, faatasi ma se ata o le lau. Iloilo mea na pasia ma talia i le tasi kiliki.","f.proof.h":"Faamaoniga, e le o folafolaga","f.proof.p":"O le tuuina atu taʻitasi e faaali ai le mea na suia: faila, eseesega, ata o le lau. E te le manaʻomia ona tatalaina polokalama uma e vaai pe ua uma.","f.chat.h":"Talanoa ma ou taʻitaʻi","f.chat.p":"O se laina e pei o Discord: le tasi ata mo poloketi taʻitasi, taimane viole mo mea e manaʻomia ai oe. Auina atu se manatu i se taʻitaʻi; e ia faia ma kāte ma se fuafuaga, faatasi ma se faamau ✅ Alu.","f.tidy.h":"E faʻatulaga e ia lava","f.tidy.p":"O kāte felavasaʻi e tuufaatasia, o ulutala fenumiai e faasaʻoina, ma o se siakiga token e tausia le code ia mamā. E le tele mea e sui ai, e le tele mea e mafaufau ai.","f.private.h":"O oe lava, i lau komepiuta","f.private.li1":"E galue le laupapa i lau lava masini ma e na o oe e tali atu ai.","f.private.li2":"O feʻau tuusao i le va o tagata ua faamaufaailogaina mai le pito i le pito.","f.private.li3":"E leai ni akauni, e leai ni mea e siaki ai oe, e leai ni cookies.","f.lang.h":"I lau gagana","f.lang.p":"E sili atu i le 120 gagana, mai le Holani, Uelisi ma Iapani i le pirate, Yoda ma Klingon, faatasi ma se sui vave i le Igilisi mo upu a le ʻau faatupu polokalama.","f.service.h":"Mai se manatu i se auaunaga moni","f.service.p":"Na e fausia se mea i le AI ua faaaoga nei e tagata? Faailoga o se auaunaga ma o le a fesoasoani le laupapa ia e faatautaia lelei: siakiga uptime, se itulau o le tulaga lautele, faalavelave ma se tusiga, suiga e manaʻomia se Go, faʻasaoga e siakiina i aso uma. E aʻoaʻo atu e le Fesoasoani laasaga taʻitasi a o e alu.","tl.aria":"Taimi mai le talanoaga muamua i le fuafuaga","tl.h2":"Mai le talanoaga muamua i mea o le a sosoo ai","tl.lede":"Aso ma taimi moni, i lou itu taimi. Ina ua mavae le aso nei o le fuafuaga, e leai ni aso o folafolaina.","tl.today":"Aso nei","tl.planned":"fuafuaina","tl.cards.one":"{n} kāte","tl.cards.other":"{n} kāte","join.h2":"Auai mai","join.lede":"O loo fausia AI-gile e se tagata laʻitiiti ma le tele o sooupu onosaʻi. O le taimi nei e faalilolilo, i se alpha tapunia ma uo. E te manaʻo e taumafai pe a tatala?","join.btn":"Lesisita le fiafia","join.small":"O le a matou tusi atu i le imeli, e leai se isi mea","footer.tag":"AI-gile. E leai ni mea e siaki ai oe, e leai ni cookies, e leai se kofe o le fono puupuu.","footer.licence":"Laisene pisinisi","footer.status":"Tulaga","footer.privacy":"Mea matou te teuina","form.sending":"O auina atu…","form.failed":"E leʻi galue: toe taumafai mulimuli ane.","form.offline":"E leʻi mafai ona oo atu i AI-gile: toe taumafai mulimuli ane.","form.keep":"Matou te faaaogaina na o le tali atu ia te oe, ona tapeese ai lea. E leai ni mea e siaki ai oe, e leai ni cookies.","form.keepLink":"Mea matou te teuina","interest.title":"AI-gile: logo mai ina ua tatala le alpha","interest.description":"Tuu mai lau imeli e iloa ai pe a tatala le alpha poʻo le beta tapunia o AI-gile.","interest.h1":"🔔 Logo mai ina ua tatala","interest.lede":"O AI-gile o loo i le pre-alpha tapunia. Tuu mai lau imeli ona matou tusi atu lea i le tasi taimi, pe a iai se avanoa mo oe.","interest.email":"Lau imeli","interest.which":"O le fea suega?","interest.alpha":"Alpha tapunia: muamua, ma le faigata, e tele suiga","interest.beta":"Beta: sili atu le mausali, mulimuli ane","interest.both":"Se tasi, po o le fea e muamua mai","interest.submit":"Tuu aʻu i le lisi","interest.thanks":"Faafetai! O iai oe i le lisi.","licence.title":"AI-gile: laisene pisinisi","licence.description":"E te faaaogaina AI-gile i lau pisinisi? Talosaga mo se laisene pisinisi e leai se totogi.","licence.h1":"📜 Laisene pisinisi","licence.lede":"E te faaaogaina AI-gile i le galuega? Taʻu mai po o ai oe ma le mea e te faia. Afai e aogā, e leai se totogi o le laisene.","licence.company":"Kamupani","licence.website":"Uepisaite","licence.what":"O le a le mea e te faia","licence.how":"Le auala e fesoasoani ai i le lalolagi","licence.email":"Imeli","licence.submit":"Talosaga","licence.thanks":"Faafetai! O le a matou toe tali atu i le imeli.","status.title":"Tulaga o AI-gile","status.h1":"Tulaga o AI-gile","status.quiet":"Ua filemu uma","status.intro":"O galue AI-gile i le taimi nei? E siaki e lenei itulau le uepisaite, faasoa o laupapa, telefoni ma le download i minute uma e 5.","status.up":"O galue (tali mai i le {ms} ms)","status.slow":"E leʻi tali mai i le siaki mulimuli, o toe taumafai","status.down":"Ua pau: e leʻi tali mai i siaki mulimuli e lua","status.svc.web":"Uepisaite","status.svc.web.offers":"Lenei saite: o le a le AI-gile, ma le pepa o le fiafia","status.svc.boards":"Faasoa o laupapa","status.svc.boards.offers":"Laupapa lautele, feʻau i le va o uo ma valaaulia","status.svc.calls":"Telefoni","status.svc.calls.offers":"Leo, vitio ma le faasoa o le lau i totonu o AI-gile","status.svc.download":"Download","status.svc.download.offers":"Le polokalama faapipii mo Windows ma fesoʻotaʻiga valaaulia","status.checking":"O siaki…","status.offline":"E le mafai ona oo atu i le auaunaga o le tulaga i le taimi nei (o toe taumafai)","status.updated":"faafouina {ago}","status.justNow":"ua na o nei","status.min":"{n} minute ua mavae","status.hours":"{n} itula ua mavae","status.days":"{n} aso ua mavae","privacy.title":"AI-gile: mea matou te teuina","privacy.h1":"Mea matou te teuina","privacy.lede":"I se faapuupuuga: na o mea e te auina mai, ma e le umi.","privacy.only":"Na o mea e te auina mai: mea e te tusia i se pepa, e pei o lau imeli. E leai se isi mea e uiga ia te oe.","privacy.sealed":"Ua faamaufaailogaina ina ia le mafai e le matou server ona faitau: i lau browser aʻo leʻi alu (i se browser tuai, i le taimi lava e taunuu ai). Na o le matou lava laupapa e mafai ona tatalaina.","privacy.server":"E tapeese mai le server i le taimi lava e oo ai i le matou laupapa. Soo se mea o i ai pea pe a mavae aso e 30 e tapeese lava.","privacy.board":"Matou te teuina i le matou laupapa seʻia matou tali atu ia te oe, ona tapeese ai foi lea iina.","privacy.none":"E leai ni mea e siaki ai oe, e leai ni cookies, e leai ni suʻesuʻega o le faaaogaina.","privacy.local":"O lau gagana ma lau filifiliga o le malamalama po o le pogisa e tumau i lau lava browser. E le auina mai lava i matou.","privacy.ask":"E te manaʻo ia vave ona tapeese? Tali mai i la matou imeli ma taʻu mai.","live.h2":"Matamata i lona fausiaina, ola","live.caption":"Ua natia kāte uma: e te va'ai i foliga o le galuega, e le o ni upu.","live.watching.one":"ola: {n} o matamata","live.watching.other":"ola: {n} o matamata","live.last.now":"Na sii le kāte mulimuli i le taimi nei lava","live.last.min.one":"Na sii le kāte mulimuli i le {n} minute ua mavae","live.last.min.other":"Na sii le kāte mulimuli i minute e {n} ua mavae","live.last.hour.one":"Na sii le kāte mulimuli i le {n} itula ua mavae","live.last.hour.other":"Na sii le kāte mulimuli i itula e {n} ua mavae","live.last.day.one":"Na sii le kāte mulimuli i le {n} aso ua mavae","live.last.day.other":"Na sii le kāte mulimuli i aso e {n} ua mavae","live.offline":"O lo'o malolo sina le fa'amaumauga ola. Toe afio mai a e le'i umi.","live.cols":"Backlog|E fai|O loʻo faia|O loʻo siaki e le 'au|Mo oe e test|Mo le 'au|Ua uma"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Tuuina."]},{"n":2,"texts":["Kanban robots.","Sui, faatulagaina.","Manatu, fausia."]},{"n":3,"texts":["Kanban mo robots.","Manatu e avea gaoioiga.","Kanban sui, leai totogi."]},{"n":5,"texts":["Laupapa kanban e taitaia e sui.","Tusi kāte. E fausia e sui.","Leai totogi, i totonu, suʻesuʻeina, malie."]},{"n":8,"texts":["Laupapa kanban leai totogi e galue ai sui AI.","Tusi se manatu. E fausia e sui. E te talia.","Agile mo se tagata ma robots onosaʻi e tele."]},{"n":13,"texts":["Laupapa kanban i lau komepiuta, e piki kāte ai sui AI e galue.","Tusi se manatu. E fausia e sui. Suʻesuʻe e siaki. Oe e talia.","Leai totogi, leai teugatupe, leai nofoaga mulimuli: se laupapa, ni robots, ma oe e pule."]},{"n":21,"texts":["O le AI-gile o se laupapa kanban mo galulue ma sui AI e tusi polokalama. E latou piki kāte; e te suʻesuʻe ma talia.","Poloketi taʻitasi e iai se taʻitaʻi ma ʻau sui AI. Tusi se faamatalaga i se kāte, ona amata lea o le galuega.","Laupapa galuega totino e leai se totogi, i lau lava komepiuta. E robots le ʻau. O oe e fai atu ioe."]},{"n":34,"texts":["Tuu manatu i luga o le laupapa. E liliu e se ʻau sui AI i gaoioiga e galue, suʻesuʻe, ma toe tuuina atu ma laasaga. E leai se mea ua uma seʻia e fai mai oe.","O le AI-gile o se laupapa kanban na fausia e Rich faatasi ma sui AI o loo ia pulea nei. E leai se totogi, e galue i lau komepiuta, ma faasoa i uo, e le faatauina.","Mafaufau i se laupapa kanban masani, ma koluma mai le Backlog i le Ua uma, ae o kāte e piki e sui AI. Latou lipotia le alualu i luma, fesili pe a tu, ma faatali pea i lau faatagaga."]},{"n":55,"texts":["O le AI-gile o se laupapa kanban e fausia le ʻau i sui AI. O poloketi taʻitasi e iai se taʻitaʻi e fuafuaina le galuega ma fesoasoani e faia. A uma se gaoioiga, e suʻesuʻe e se AI suʻesuʻe ma ave ai se ata o le mataʻitusi, ona alu lea i lau faaputuga. Talia, pe tusi se faamatalaga ona toe faia lea e latou.","Na amata o se auala e mulimuli ai le tagata e tasi i le tele o fonotaga tusi polokalama AI, ona tupu lea i se laupapa moni. E galue i lau masini, e leai se teugatupe, e leai ni nofoaga mulimuli. E leai se totogi mo uo. E le i uma, ia faatalitali i ni pito faigata.","O le faamatalaga faamaoni lea. E tatau pea ona e maua manatu, ma e tatau pea ona e siaki taunuuga. O le AI-gile e faia mea uma i le va: e tausia kāte i le faasologa, ala le sui saʻo pe a e tusi se faamatalaga, faaali saʻo le mea na suia, ma tuu mea uma i se faaputuga puupuu mo oe."]},{"n":89,"texts":["O le AI-gile o se laupapa kanban e leai se totogi i lau komepiuta. I poloketi taʻitasi e iai se ʻau sui AI: se taʻitaʻi e liliu au manatu i kāte ma se fuafuaga, ma fesoasoani e piki kāte. A fausia se mea, e mulimuli se AI suʻesuʻe i laasaga ma faaali le mea na ia vaai i ai. Ona faatali lea i se faaputuga e igoa Mo oe. E te talia, pe tusi se faamatalaga ona toe taumafai lea. E leai se mea e oo i le Ua uma e aunoa ma oe.","Nisi mea e te le faatalitalia. O se leoleo po e faatumu le koluma E fai a e moe oe, ma filifili kāte e le manaʻomia ai se tali. O se tagaga token e faaali le aofaʻi e faaaoga e sui, ma o le Auala e leai ni token e taofi ai. E mafai ona e feʻau atu i uo, faamaufaailogaina mai le pito i le pito. E tautala le laupapa i le tusa ma le 120 gagana, e aofia ai Holani, pirate ma Klingon. E leai se totogi, ma e leai se tasi o taumafai e faatau atu.","O le AI-gile o se poloketi laʻitiiti totino, e le o se kamupani. Na manaʻo Rich e tausia ni poloketi tusi polokalama AI e aunoa ma le tatalaina o polokalama uma, o lea na ia fausia ai se laupapa faatasi ma sui, ona faaaoga lea e fausia le vaega o totoe. O loo i le pre-alpha tapunia: e galue, e tele lava, mo ni uo e toʻaitiiti. E leai se itulau o tau, e leai se nusipepa. Afai e aogā, talosaga e taumafai pe a sili atu le tatala."]},{"n":144,"texts":["O le AI-gile o se laupapa kanban mo le tagata e tasi ma le tele o sui AI. E galue i lau lava komepiuta ma e leai lava se totogi. E te faaopoopo poloketi, ma taʻitasi e maua se taʻitaʻi ma se ʻau laʻitiiti. E te talanoa ma le taʻitaʻi, e pei o Discord, ma faamatala se manatu; e liliu e le taʻitaʻi i kāte ma se fuafuaga, ona faatali lea seʻia e kiliki Alu. E faia e le ʻau kāte e tusa ai ma le faamuamua, e faaaoga se laina poloaiga faigofie na faia mo faiga gagana. Aʻo leʻi toe foʻi se mea ia te oe, e mulimuli se AI suʻesuʻe i laasaga i se kopi o le polokalama ma faapipiʻi se ata o le mataʻitusi. O galuega ua uma e oo i lau faaputuga faatasi ma faila ua suia ma eseesega. E te talia, pe tuu se faamatalaga ona ala lea o le ʻau ma toe taumafai. Na o oe e mafai ona e suia se kāte i le Ua uma.","O se aso ma AI-gile, tusa lava. I le afiafi e te tuu ni faamatalaga: o lenei faamau o loo i se mea sese, o lena lisi e tatau ona faatulagaina, e mafai ona tatou maua se auala pogisa. E te alu e moe. E faitau e sui faamatalaga, faia suiga, suʻesuʻe ma toe tuuina atu ia te oe. Afai e mutu le koluma E fai, e faatumuina e le leoleo po mai le backlog i kāte e le manaʻomia ai se tali mai ia te oe. I le taeao o loo iai se faaputuga puupuu: ni fesili e ono ma ni mea e suʻesuʻe, taʻitasi ma laasaga e mafai e se tagata moeiini ona mulimuli ai ma se ata o loo galue. E te alu i totonu, talia mea lelei ma toe auina atu isi. Ona e taumafa lea o le taeao, lea e le mafai pea e sui ona fesoasoani i ai.","Muamua, le mea e le o le AI-gile. E le o se startup, e le o faatauina, ma e leai se tasi o aoina au faamatalaga. O se laupapa e leai se totogi e galue i lau komepiuta, e leai ni teugatupe, e leai ni nofoaga mulimuli ma e leai ni cookies. O le mea e iai: o se nofoaga e tasi mama e vaai ai i poloketi tusi polokalama AI uma i le taimi e tasi, ma se ʻau o sui e faia kāte ma oe e faia filifiliga. E tuufaatasia kāte felavasaʻi, faasaʻo ulutala fenumiai, ma mataʻituina ia tumau le code vaivai. E tautala i le tusa ma le 120 gagana, mai le Holani ma le Flemish i le pirate ma le Klingon. O loo i le pre-alpha tapunia, o lea e faigata i nisi pito. Afai e foliga manaia, talosaga ma le agalelei ona e maua lea ma le vave."]}],"quips":{"1":"Le upu e tasi. Natia. Masalo e sili.","3":"Upu e tolu. E sili atu le faamaoni nai lo le tele o itulau o oloa.","8":"Upu e valu. E puupuu pea nai lo se fono puupuu.","21":"O umi o story points, i le ala. Ioe, e faapea lava.","55":"Upu e lima sefulu ma le lima. E lua kāte na uma aʻo e faitau.","144":"O le mea umi lea. E leai se 233. Ua alu e moe sui."}},"timeline":{"first-idea.name":"Le manatu muamua","first-idea.line":"O le talanoaga sili ona muamua, aʻo leʻi iai se code.","first-board.name":"Le laupapa muamua","first-board.line":"O se laupapa e mulimuli i lona lava fausiaga: kāte, koluma, toso ma tuu, poloketi.","team-roles.name":"ʻAu ma tofiga","team-roles.line":"Faamatalaga o sui, faʻataʻitaʻiga o ʻau, avanoa ma o ai e faia le a.","install.name":"Faapipiʻiga ma lomiga","install.line":"O se zip e mafai e se uo ona faapipii, faafouga otometi, auala ma toe foʻi.","usage-saver.name":"Faasaoina o le faaaogaina","usage-saver.line":"Fuaina le tau o le faatinoga, tausia le code e vaivai, faasaoina lau tapulaa.","friends.name":"Uo ma le faasoaina","friends.line":"Feʻau tuusao, se relay faalilolilo, valaaulia, tofiga ma poloketi faasoa.","languages.name":"Gagana","languages.line":"O tusitusiga uma o le mataʻitusi i se faila gagana, ma le Holani ma le Flemish muamua.","ai-tester.name":"AI suʻesuʻe","ai-tester.line":"E muamua siaki e se suʻesuʻe tuuina atu uma ma faaali le mea na ia vaai i ai.","website.name":"Le initaneti","website.line":"aigile.lol, le teaser ma lenei taimi.","streaming.name":"Talanoaga ma faasalalauga","streaming.line":"Discord, Twitch, OBS, auala faasalalau, GIF ma emoji.","no-ai.name":"Lomiga e leai se AI","no-ai.line":"O se laupapa mo tagata e tusi polokalama e aunoa ma AI, ma laupapa lautele.","night-watch.name":"Leoleo po","night-watch.line":"O se leoleo ma se Scrum Master e tausia ʻau i galuega a e moe oe.","p-more.name":"Isi mea uma","p-more.line":"Manatu laiti o loo faatali pea i le latou taimi.","p-android.name":"Telefoni ma Android","p-android.line":"Oo atu i lau laupapa mai se telefoni, ona sosoo ai lea ma se polokalama Android.","p-release.name":"Alpha ma mulimuli ane","p-release.line":"Alpha tapunia, le initaneti ola, ona sosoo ai lea ma le beta.","p-languages.name":"Sili atu gagana","p-languages.line":"Sili atu i le selau gagana, ma se auala tofo mo tagata aʻoaʻo.","p-engines.name":"Sili atu afi AI","p-engines.line":"Filifili Claude, Codex poʻo Gemini mo sui taʻitasi.","p-pro.name":"Faiga faapolofesa","p-pro.line":"Faailoga o lamatiaga, faitotoʻa tuufaatasia, kāte o mea e tutupu ma puipuiga.","p-self.name":"Tausia oe","p-self.line":"Auala o le vaivai, faamanatu o le tausiga o oe lava ma le 4:20.","p-servers.name":"Server ma le tuputupu aʻe","p-servers.line":"Setiina lautele o server, tofiga ma fuafuaga mo le tuputupu aʻe.","p-livestream.name":"Faaopoopoga faasalalau","p-livestream.line":"Talanoaga Twitch, emoji faapitoa ma se vaaiga ola lautele."},"words":{"button":"📖 Upu o le atinaʻe","h":"📖 Upu ua faamatalaina","intro":"O upu e te feiloaʻi ai i le AI-gile, i se gagana faigofie: o le fausiaina, o le suia ma le saogalemu, o le faagaoioia pea mo tagata e faʻaaogaina, ma le galulue faatasi o se ʻau ma le AI.","search":"Su'e se upu…","none":"E leai se upu e fetaui.","close":"Tapuni","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Fausiaina"},{"id":"change","name":"🔀 Suia ma le saogalemu"},{"id":"run","name":"🛎️ Faagaoioia o se auaunaga"},{"id":"team","name":"🤝 Galulue o se ʻau (ma le AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"O le pusa faila o le poloketi o le code ma lona tala atoa o commits, e masani ona teuina foi i le GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"O se laina e ese o galuega i le code, ina ia mafai ona faia suiga e aunoa ma le paʻi i le lomiga autu.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"O se ata ua teuina o le code, faatasi ai ma se faʻamatalaga puʻupuʻu o le mea na suia. E mafai ona e toe foʻi i se tasi i so'o se taimi.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"O le auina atu o ata ua teuina (commits) mai lenei komipiuta i le GitHub, ina ia teuina ma faasoa."},{"id":"merge","g":"build","word":"Merge","text":"O le toe tuufaatasia o suiga a se branch i le lomiga autu."},{"id":"pr","g":"build","word":"Pull request","text":"O le ole atu e siaki ma tuufaatasia suiga a se branch i le lomiga autu.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"O le faʻamama o le code e aunoa ma le suia o mea e faia: faila laiti, igoa manino, e itiiti le toe faia."},{"id":"bug","g":"build","word":"Bug","text":"O se mea e le galue e pei ona tatau.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"O le taumafai i se galuega ua uma e siaki pe faia le mea na ole atu ai, a o leʻi taliaina.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"O le faapuupuuga o le quality assurance: o siaki otometi e faia a o leʻi ola se mea. A mumu le QA, ua toilalo se mea, ma e le mafai ona ola seʻia toe faasaʻo.","also":["siaki o le tulaga lelei","quality assurance"]},{"id":"deploy","g":"change","word":"Deploy","text":"O le tuuina atu o se lomiga fou ia ola, e pei o se sava e faʻaoga ai e tagata."},{"id":"release","g":"change","word":"Lomiga","text":"O se fusi ua faaigoaina o galuega ua uma e ola faatasi, faatasi ai ma ni faamatalaga puupuu o mea na suia. E tusia e 🚀 Lomiga ia faamatalaga mai kāte ua uma.","also":["lomiga fou","release","releases"]},{"id":"rollback","g":"change","word":"Toe faafoi","text":"O le toe foʻi i le lomiga mulimuli na aoga pe a faʻatupu faʻafitauli se lomiga fou. I le AI-gile e faia ai se lisi siaki o laasaga e toe faaleaogaina ai, na tusia i suiga taʻitasi.","also":["rollback","roll back","ua toe faafoi"]},{"id":"live","g":"change","word":"Ola","text":"O le lomiga moni e faʻaaogaina e tagata, e ese mai i se kopi e taumafai ai mea. E taʻua foʻi e le au atiaʻe o le production.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Suiga","text":"O se suiga ua fuafuaina i se mea e faalagolago i ai tagata, e tusia muamua: o le a, aisea, le lamatiaga, afea, ma le auala e toe faaleaogaina ai. Amata i le 🔀 Talosaga se suiga.","also":["suiga","talosaga mo se suiga","change"],"noTip":1},{"id":"risk","g":"change","word":"Lamatiaga","text":"O se mea e ono sese, ua fuaina i le avanoa e tupu ai ma le leaga pe a tupu. E teuina e ⚠️ Lamatiaga i se lisi e tasi, o le togi maualuga muamua, e taʻitasi ma se aso e toe vaai ai.","also":["lamatiaga","risk","risks"]},{"id":"chgwin","g":"change","word":"Faamalama o suiga","text":"O taimi e mafai ai ona ola suiga, e pei o se afiafi filemu o le Aso Lua. I fafo atu o se faamalama, e le mafai ona faauma se kāte suiga, vagana ua faafuaseʻi.","also":["faamalama o suiga","change window"]},{"id":"gonogo","g":"change","word":"Alu / aua le alu","text":"O se palota vave a o leʻi ola se suiga: o tagata taʻitasi e tatau ona faatagaina e fai mai Alu pe Aua le alu. E faaauau pe a malilie uma.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Faatagaga","text":"O le faatali mo se ioe a o leʻi amata le galuega. O se kāte e talosagaina e se uo, po o se suiga, e faatali i ✅ Faatagaga seʻia e talia pe teena.","also":["faatagaga","approval"]},{"id":"quiettime","g":"change","word":"Taimi filemu","text":"O se vaitaimi, e pei o se stream, se faataʻitaʻiga po o le po, e leai se mea e ola ai. E faaauau pea ona galulue ma suʻe le ʻau, ae e faatali le ola seʻia uma. I isi nofoaga e taʻua o le change freeze.","also":["taimi filemu","change freeze"]},{"id":"service","g":"run","word":"Auaunaga","text":"O se mea na e fausia e faalagolago i ai tagata, e pei o se upegatafaʻilagi po o se app, e tausia ina ia aoga pea. Faailoga le “O lenei poloketi o se auaunaga” ma taʻu le mea e ofo atu, o ai e faʻaaogaina, ma o ai o loo i le tiute.","also":["auaunaga","service"]},{"id":"uptime","g":"run","word":"Siaki o le ola","text":"O se siaki otometi, i minute nai taʻitasi, pe o tali mai pea lau auaunaga. Afai e toilalo faafaasolo ni nai taimi, e tatala e le AI-gile lava ia se kāte o se mea ua tupu.","also":["uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Itulau o le tulaga","text":"O se itulau lautele e faaali ai pe o aoga se auaunaga (lanu meamata, moli po o le mumu) ma le tala fou lata mai, ina ia mafai e tagata e faʻaaogaina ona siaki nai lo le fesili.","also":["status page"]},{"id":"incident","g":"run","word":"Mea ua tupu","text":"O se mea ua malepe i le taimi nei mo tagata o loo faʻaaogaina, e pei o le upegatafaʻilagi ua pau. E muamua le kāte 🔥 mea ua tupu i le laina: o le toe faaaogaina o le mea muamua.","also":["faalavelave","incident"]},{"id":"major","g":"run","word":"Mea ua tupu tele","text":"O se mea ua tupu tele: e toʻatele tagata ua aʻafia, po o tupe po o faamaumauga ua lamatia. E tasi le faamau e tuʻu ai ʻau uma i ai (fuifui), fafagu le tagata o loo i le tiute, ma talosaga mo se tala fou o le tulaga i minute e 30 taʻitasi.","also":["faalavelave tele","major incident"]},{"id":"oncall","g":"run","word":"I le tiute","text":"O le avea ma tagata e tali pe a malepe se mea, e oo lava i le po. O auaunaga taʻitasi e iai se sui o le ʻau o loo i le tiute e fafagu muamua mo ona mea ua tutupu.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Taimi o tali","text":"Le umi e mafai ai e se kāte ona faatali mo se tali muamua, mo se faataʻitaʻiga e tasi le itula mo se mea ua tupu. A uma lea e maua ai se uati mumu, ina ia leai se mea e galo filemu. E taʻua foʻi o le taimi faatulagaina o tali.","also":["taimi o tali","response target"]},{"id":"postmortem","g":"run","word":"Iloiloga pe a uma","text":"O se toe tilotilo puupuu pe a uma se mea ua tupu: o le mea na tupu, o le mea na fesoasoani, ma le mea e suia, e aunoa ma le tuuaʻia o se tasi. E le mafai ona tapunia se mea ua tupu e aunoa ma se tasi.","also":["post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Faʻafitauli","text":"O le mafuaaga lilo i tua o se tasi pe sili atu mea ua tutupu. E faapotopoto e se kāte 🧩 faʻafitauli mea ua tutupu e toe foʻi mai pea, ina ia maua le mafuaaga ma faasaʻo e faavavau.","also":["faafitauli","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Mafuaaga autu","text":"O le mafuaaga moni na malepe ai se mea, ae le na o le mea na e vaaia ua sese. Faasaʻo le mafuaaga autu ona le toe foʻi mai lea o le mea ua tupu.","also":["root cause"]},{"id":"workaround","g":"run","word":"Fofo mo le taimi nei","text":"O se auala e aoga pea ai mea seʻia sauni le faasaʻoga moni, e pei o le toe amataina o se mea pe a mau. E tusia i le kāte faʻafitauli ina ia le toe sailia e se tasi.","also":["workaround"]},{"id":"knownerror","g":"run","word":"Mea sese ua iloa","text":"O se faʻafitauli ua malamalama i lona mafuaaga ma e iai se fofo mo le taimi nei, ae leʻi faasaʻoina. E lisi e 🧩 Mea sese ua iloa, ina ia faʻaaoga e tagata uma le fofo mo le taimi nei nai lo le toe eli.","also":["known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"O faatonuga laasaga ma laasaga e faasaʻo ai se ituaiga faʻafitauli ua iloa, ina ia faia i le auala lava e tasi, vave, i taimi uma. A uma se mea ua tupu tele, e mafai e le ʻau ona fautuaina se tasi mo lau ioe.","also":["runbooks"]},{"id":"backup","g":"run","word":"Kopi faasao","text":"O se kopi ua teuina o au faamaumauga mai muamua, e toe faalagolago i ai pe a leiloa pe faaleagaina se mea. E faia e le AI-gile se kopi faasao o au laupapa i aso uma.","also":["backup","backups"]},{"id":"restore","g":"run","word":"Toe aumai","text":"O le toe tuʻuina mai o faamaumauga mai se kopi faasao. E moni lava le aoga o se kopi faasao pe a e iloa e mafai ona toe aumai, o lea e lelei ona taumafai i lea taimi ma lea taimi.","also":["restore","toe faafoi mai"]},{"id":"backlog","g":"team","word":"Backlog","text":"Manatu ma galuega e leʻi fuafuaina. E leai se mea iina e galueina seʻia siitia i le E fai."},{"id":"sprint","g":"team","word":"Sprint","text":"O se vaitaimi puʻupuʻu o galuega (e masani ose vaiaso po o le lua) ma se aofa'iga o kāte ua maliega e faamaeaina.","also":["sprints"]},{"id":"standup","g":"team","word":"Fonotaga puʻupuʻu","text":"O se siakiga vave: o le a le mea na faia e sui taʻitasi o le 'au, o le a le mea latou te faia a sosoo, ma le mea o taofia ai i latou.","also":["standup","stand-ups","stand-up"]},{"id":"kanban","g":"team","word":"Kanban","text":"O se laupapa e iai koluma (E fai, O faia, Ua uma) e siitia ai kāte mai le agavale i le taumatau a o faia galuega."},{"id":"wip","g":"team","word":"Tapulaʻa WIP","text":"Galuega o faagaoioi: le tele aupito o kāte e tatau ona taofi e se koluma, ina ia faamaea e le 'au mea a o leʻi amata nisi.","also":["WIP","WIP limit"]},{"id":"dod","g":"team","word":"Faauigaga o le Uma","text":"O le lisi siaki puupuu a le ʻau o le uiga o le “uma”, e pei o le ua suʻeina ma faamatalaina, a o leʻi tuuina atu se kāte iā te oe. O lona masaga, o le Faauigaga o le Sauni, e faailoa mai pe a manino lelei se kāte e amata ai.","also":["Definition of Done","Faauigaga o le Sauni","Definition of Ready"]},{"id":"testpile","g":"team","word":"Faaputuga suʻega","text":"O kāte ua uma o loo faatali mo oe e taumafai ai, tasi i le tasi. Talia se tasi pe toe faafoi atu ma se faamatalaga, ona sau ai lea o le isi.","also":["test pile"]},{"id":"retro","g":"team","word":"Toe iloilo","text":"O se toe tilotilo i le auala e galue ai le ʻau, e malilie ai i se mea e tasi e faaleleia. I le AI-gile e fautuaina e se toe iloilo se suiga i auala o galuega a le ʻau, ma e te fai mai Alu pe Leʻi taimi.","also":["retro","retrospective"]},{"id":"peerreview","g":"team","word":"Iloiloga a paaga","text":"O se isi pea mata: e siaki e se isi AI le galuega a kāte taʻitasi a o leʻi oʻo mai iā te oe, ina ia itiiti ni mea sese e pasi atu.","also":["peer review","code review"]},{"id":"swarm","g":"team","word":"Fuifui","text":"Lima uma i le galuega: e tuu e ʻau uma isi galuega e fesoasoani i se poloketi faanatinati e tasi seʻia foia. E faatali isi poloketi i le taimi lea.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"O le tagata e tausia le tafe o galuega: vaaia kāte ua mau, unaʻia ʻau, ma faamanatu atu iā te oe mea o loo faatali. I le AI-gile e faia lenei mea e le Lead Scrum Master i poloketi uma.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Sooupu","text":"O se AI e galue na o ia i se galuega: faitau le code, faia suiga, faagaoioi siakiga, ma lipotia mai.","also":["agent","agents","sooupu"]},{"id":"token","g":"team","word":"Token","text":"O le iunite e faitauina ai le faʻaaogaina o le AI: pe tusa ma ni nai mataitusi o tusitusiga ua faitau po o tusia. E itiiti token, e tele totoe o lau fuafuaga.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"O se poloaiga laiti e faagaoioi e ia lava i se taimi ua seti, e.g. pe a amata se sesisi AI, ina ia faʻalogo le 'au i au faʻamatalaga.","also":["hooks"]}]}};
